{"path": "stage1.py", "content": "import csv


def parse_orders(path):
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append({
                "id": int(row["id"]),
                "qty": int(row["qty"]),
                "price": int(row["price"]),
            })
    return rows
"}

{"path": "stage3.py", "content": "def total_by_price(rows):
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
"}

{"path": "stage4.py", "content": "def report(totals):
    lines = [f"{price}:{totals[price]}" for price in sorted(totals)]
    return "".join(line + "\n" for line in lines)
"}
